-- 019_revelation_port
--
-- Mounts + costumes imported from the 4Revelation client (Tools/GenesisPort `rev-port --apply` - generated, do not edit by hand).
--   TMONSTERCHART: 65 mount recall monsters (31979, 31980, 31981, 31982, 31983, 31984, 31985, 31986, 31987, 31988, 31989, 31990, 31991, 31992, 31993, 31994, 31995, 31996, 31997, 31998, 31999, 32000, 32001, 32002, 32003, 32004, 32005, 32006, 32007, 32008, 32009, 32010, 32011, 32012, 32013, 32014, 32015, 32016, 32017, 32018, 32019, 32020, 32021, 32022, 32023, 32024, 32025, 32026, 32027, 32028, 32029, 32030, 32031, 32032, 32033, 32034, 32035, 32036, 32037, 32038, 32039, 32040, 32041, 32042, 32043), clones of 31025 (Brown Horse).
--   TMOUNTCHART:   65 mounts (137-201), plain / saddled recall monster.
--   TITEMCHART:    66 mount items (clones of 30261) + 90 costumes
--                  (hats clone 12059, outfits 12061, wings 25004); client-file fields overwritten.
-- NOTE: chart tables load once at startup - RESTART TMapSvr/TWorldSvr after applying.
-- Idempotent: every insert is guarded by IF NOT EXISTS.
USE [TGame_gsp];
GO

SET NOCOUNT ON;
GO

-- 31979  Mechanic Snowmobile
IF NOT EXISTS (SELECT 1 FROM dbo.TMONSTERCHART WHERE wID = 31979) AND EXISTS (SELECT 1 FROM dbo.TMONSTERCHART WHERE wID = 31025)
BEGIN
    SELECT * INTO #m FROM dbo.TMONSTERCHART WHERE wID = 31025;
    UPDATE #m SET wID = 31979;
    INSERT INTO dbo.TMONSTERCHART SELECT * FROM #m;
    DROP TABLE #m;
END
GO
